style.css:
/* Midnight Redmond - dark mode for Microsoft pages */

:root {
  /* swap this: it's the page background BEFORE inversion, so a light gray becomes a dark gray (#eee -> #111, #fff -> pure black) */
  --my-page-bg: #eeeeee;
}

/* flip the whole page to dark */
html {
  background-color: var(--my-page-bg) !important;
  filter: invert(1) hue-rotate(180deg) !important;
}

/* flip media back so pictures keep their real colors */
img,
picture,
video,
canvas,
iframe {
  filter: invert(1) hue-rotate(180deg) !important;
}
